cat > /tmp/repro.test.ts << 'EOF'
import { describe, test, expect } from "vitest";
import { cac } from "../src/index.ts";

describe("repro: default leak to aliases", () => {
  test("default should NOT leak to alias when other alias is parsed", () => {
    const cli = cac();
    cli.option("-b, --base-url <baseUrl>", "Set the instance URL", {
      default: "https://github.com",
    });
    const { options } = cli.parse(["node", "bin", "--base-url", "https://gitlab.com"]);
    expect(options.baseUrl).toBe("https://gitlab.com");
    // b should NOT have the default
    expect(options.b).toBeUndefined();
  });

  test("default SHOULD apply to all aliases when nothing parsed", () => {
    const cli = cac();
    cli.option("-b, --base-url <baseUrl>", "Set the instance URL", {
      default: "https://github.com",
    });
    const { options } = cli.parse(["node", "bin"]);
    expect(options.baseUrl).toBe("https://github.com");
    expect(options.b).toBe("https://github.com");
  });
});
EOF
